#!/usr/bin/env bash
# Integration test: runs the CLI on real and synthetic DNGs and checks the output with exiftool.
#   - synthetic samples (generated by the unit test target)
#   - testdata/downloaded/  (CC0 samples from raw.pixls.us, see scripts/fetch-samples.py)
#   - testdata/local/       (your own photos – git-ignored, never committed)
# Originals are never modified: everything is written to a temporary output folder.
#
# usage: scripts/integration-test.sh [--require-real]
set -euo pipefail
cd "$(dirname "$0")/.."

REQUIRE_REAL=0
[[ "${1:-}" == "--require-real" ]] && REQUIRE_REAL=1

command -v exiftool >/dev/null || { echo "exiftool missing (macOS: brew install exiftool)"; exit 2; }

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

echo "== Building CLI"
swift build --product pano-squeezer-cli >/dev/null
CLI="$(swift build --show-bin-path)/pano-squeezer-cli"

echo "== Generating synthetic samples"
PANO_SAMPLE_DIR="$WORK/in/synthetic" swift test --filter SampleExport >/dev/null 2>&1

# Collect inputs (copies, so originals are never touched – the CLI only reads anyway).
real=0
for dir in testdata/downloaded testdata/local; do
    [[ -d "$dir" ]] || continue
    while IFS= read -r -d '' f; do
        mkdir -p "$WORK/in/real"
        cp "$f" "$WORK/in/real/$(basename "$dir")-$(basename "$f")"
        real=$((real + 1))
    done < <(find "$dir" -maxdepth 1 -type f -iname '*.dng' ! -name '.*' -print0)
done
echo "== $real real DNG(s)"
if [[ $REQUIRE_REAL == 1 && $real == 0 ]]; then
    echo "FAIL: no real DNG samples found"; exit 1
fi

fail=0
check() {  # check <factor> <exiftool-value> [--vertical]
    local factor="$1" expected="$2" flag="${3:-}"
    local out="$WORK/out-$factor$flag"
    "$CLI" --factor "$factor" $flag --recursive --out "$out" "$WORK/in"
    local folder
    folder="$(find "$out" -mindepth 1 -maxdepth 1 -type d)"
    while IFS= read -r -d '' src; do
        local rel="${src#"$WORK/in/"}"
        local dst="$folder/$rel"
        local name
        name="$(basename "$src")"
        if [[ ! -f "$dst" ]]; then echo "FAIL $name: no output"; fail=1; continue; fi

        # 1. DefaultScale is set in the raw IFD.
        local got
        got="$(exiftool -a -G1 -s -DefaultScale "$dst")"
        if ! grep -q ": $expected\$" <<<"$got"; then
            echo "FAIL $name: DefaultScale = '$got', expected '$expected'"; fail=1; continue
        fi
        # 2. No new exiftool validation warnings compared with the original.
        diff <(exiftool -validate -warning -a -s "$src" | grep -v -e FileName -e Directory | sort) \
             <(exiftool -validate -warning -a -s "$dst" | grep -v -e FileName -e Directory | sort) >/dev/null \
            || { echo "FAIL $name: new validation warnings"; \
                 diff <(exiftool -validate -warning -a -s "$src" | sort) <(exiftool -validate -warning -a -s "$dst" | sort) || true; \
                 fail=1; continue; }
        # 3. Original bytes unchanged except the 4 pointer bytes.
        local size changed
        size=$(wc -c <"$src")
        changed=$(cmp -l -n "$size" "$src" "$dst" | wc -l || true)
        if (( changed < 1 || changed > 4 )); then
            echo "FAIL $name: $changed original bytes changed"; fail=1; continue
        fi
        echo "ok   $name  ($got)"
    done < <(find "$WORK/in" -type f -iname '*.dng' -print0)
}

echo "== Horizontal 1.33"
check 1.33 "1.33 1"
echo "== Vertical 2"
check 2 "1 2" --vertical

if [[ $fail != 0 ]]; then echo "INTEGRATION TEST FAILED"; exit 1; fi
echo "INTEGRATION TEST PASSED"
